package hu.bankmonitor.payments.accounts;

import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/**
 * The Account endpoints.
 *
 * <p>It holds no repository — the boundary {@code ModuleBoundariesHoldTest} enforces —
 * and no rule of its own: what a request may say is declared as constraints on
 * {@link CreateAccountRequest}, so a refusal is the one problem document of design
 * decision 18 with an entry naming the field, rather than a check written by hand here.
 */
@RestController
@RequestMapping(AccountController.PATH)
class AccountController {

	static final String PATH = "/api/accounts";

	private final AccountService accounts;

	AccountController(AccountService accounts) {
		this.accounts = accounts;
	}

	/**
	 * Answers {@code 201} with the created Account, and deliberately without a
	 * {@code Location} header: this API has no single-Account resource for one to point
	 * at, and a header addressing a {@code 404} would be worse than its absence. The body
	 * carries the identifier, which is what a caller needs. See
	 * {@code docs/deferred.md}.
	 */
	@PostMapping
	@ResponseStatus(HttpStatus.CREATED)
	AccountResponse openAccount(@Valid @RequestBody CreateAccountRequest request) {
		return AccountResponse.of(accounts.open(request.openingBalance()));
	}
}
package hu.bankmonitor.payments.accounts;

import hu.bankmonitor.payments.common.Money;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * What can be done to an Account, and the only way in from outside this package.
 *
 * <p>The class is package-private and the methods are public, which is the shape design
 * decision 30 warns is load-bearing: {@code @Transactional} on a non-public method is
 * silently ignored under proxy-based AOP, so a transaction would quietly stop existing
 * with no error to read.
 */
@Service
class AccountService {

	private final AccountRepository accounts;

	AccountService(AccountRepository accounts) {
		this.accounts = accounts;
	}

	/**
	 * Opens an Account holding the given amount, in the currency that amount is
	 * denominated in, and returns it with the identifier the database gave it.
	 */
	@Transactional
	public Account open(Money openingBalance) {
		return accounts.save(new Account(openingBalance));
	}
}
package hu.bankmonitor.payments.accounts;

import org.springframework.data.repository.Repository;

/**
 * The accounts table, reachable only from inside this package.
 *
 * <p>Extends the bare {@link Repository} marker and declares the one method this slice has
 * a caller for, rather than {@code JpaRepository} and its forty inherited ones. Spring
 * Data implements what is declared and nothing else, so {@code deleteAll} is not a thing
 * an accounts balance can be reached by — and the interface stays a list of what the slice
 * actually does. Ticket 10 adds the query that lists accounts and ticket 12 the one that
 * locks them, each against a call site rather than ahead of one.
 */
interface AccountRepository extends Repository<Account, Long> {

	Account save(Account account);
}
package hu.bankmonitor.payments.accounts;

import hu.bankmonitor.payments.common.Currency;
import hu.bankmonitor.payments.common.Money;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * What opening an Account takes: the currency it is denominated in, and how much it holds
 * to begin with.
 *
 * <p>The amount is a whole count of Minor Units and <b>the field name says so</b>.
 * {@code 10050} in a field called {@code openingBalance} reads as ten thousand and fifty
 * euros to one caller and as a hundred euros fifty to the next; a field called
 * {@code openingBalanceMinorUnits} has one reading. The decimal form an operator types
 * belongs to the form, which converts it before it ever leaves the browser.
 *
 * <p>{@link Currency} rather than a string, so the three denominations this service can
 * quote are a closed set in the generated OpenAPI schema too, and the frontend picks the
 * same list up rather than restating it.
 *
 * <p>Both components are boxed and {@code @NotNull} rather than primitive: a primitive
 * {@code long} that no JSON member filled would arrive as a perfectly valid zero, and an
 * absent field would open an empty Account instead of being refused.
 */
record CreateAccountRequest(

		@NotNull Currency currency,

		@NotNull @PositiveOrZero Long openingBalanceMinorUnits) {

	/**
	 * The two components as the one value the domain has for them — never called before
	 * validation has run, which is what lets it dereference both.
	 */
	Money openingBalance() {
		return new Money(openingBalanceMinorUnits, currency);
	}
}
package hu.bankmonitor.payments.accounts;

import hu.bankmonitor.payments.common.Currency;

/**
 * An Account as this API reports it: what it holds, and how much of that is still
 * spendable.
 *
 * <p>One representation for every endpoint that answers with an Account, rather than a
 * leaner one for the Account just created. The two figures are what an operator reads —
 * the Reserved Amount is their difference and would be a third number saying nothing new
 * — and a create response shaped differently from a list entry would hand the frontend
 * two Account types generated from one document.
 *
 * <p>Amounts are counts of Minor Units, named as such for the reason
 * {@link CreateAccountRequest} gives.
 */
record AccountResponse(

		long id,

		Currency currency,

		long balanceMinorUnits,

		long availableBalanceMinorUnits) {

	static AccountResponse of(Account account) {
		return new AccountResponse(
				account.getId(),
				account.getCurrency(),
				account.getBalance().minorUnits(),
				account.getAvailableBalance().minorUnits());
	}
}

