import java.lang.reflect.Method;
import java.util.Arrays;

public class CountJpaRepositoryMethods {
	public static void main(String[] args) throws Exception {
		Class<?> jpa = Class.forName("org.springframework.data.jpa.repository.JpaRepository");
		Method[] all = jpa.getMethods();
		System.out.println("JpaRepository.getMethods() (declared + inherited, public): " + all.length);
		long distinct = Arrays.stream(all).map(Method::getName).distinct().count();
		System.out.println("distinct method names: " + distinct);
		Arrays.stream(all).map(Method::getName).distinct().sorted().forEach(n -> System.out.println("  " + n));
	}
}

